// blitz-lsp: the language server of BlitzLLVM, which talks to the editor over standard input and output.
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include "server.hpp"
#include "stack.hpp"
#if defined(_WIN32)
#include <fcntl.h>
#include <io.h>
#include <windows.h>
#else
#include <unistd.h>
#if defined(__APPLE__)
#include <mach-o/dyld.h>
#endif
#endif

namespace {
	std::filesystem::path executable_path()
	{
#if defined(_WIN32)
		wchar_t buffer[32768];
		DWORD   length = GetModuleFileNameW(nullptr, buffer, DWORD(std::size(buffer)));
		return std::filesystem::path(std::wstring(buffer, length));
#elif defined(__APPLE__)
		char     buffer[4096];
		uint32_t size = sizeof(buffer);
		if (_NSGetExecutablePath(buffer, &size) == 0) return std::filesystem::weakly_canonical(buffer);
		return {};
#else
		std::error_code ec;
		return std::filesystem::read_symlink("/proc/self/exe", ec);
#endif
	}

	// A file of the installation: next to the executable, or in share/blitzllvm of the prefix.
	std::filesystem::path find_data(const char* env, const char* name, bool directory)
	{
		if (const char* value = std::getenv(env); value && *value) return value;
		auto bin = executable_path().parent_path();
		for (auto const& candidate : { bin / name, bin / ".." / name, bin / ".." / "share" / "blitzllvm" / name }) {
			std::error_code ec;
			if (directory ? std::filesystem::is_directory(candidate, ec) : std::filesystem::is_regular_file(candidate, ec)) {
				return std::filesystem::weakly_canonical(candidate, ec);
			}
		}
		return {};
	}

	// Input with a buffer of our own, so that the server can tell when nothing is waiting and analyse then.
	class input {
		std::string _buffer;
		size_t      _at = 0;

		public:
		bool pending() const { return _at < _buffer.size(); }

		bool fill()
		{
			char buffer[65536];
#if defined(_WIN32)
			int got = _read(0, buffer, sizeof(buffer));
#else
			ssize_t got = ::read(0, buffer, sizeof(buffer));
#endif
			if (got <= 0) return false;
			if (_at > 0) {
				_buffer.erase(0, _at);
				_at = 0;
			}
			_buffer.append(buffer, size_t(got));
			return true;
		}

		bool read_line(std::string& line)
		{
			for (;;) {
				auto end = _buffer.find('\n', _at);
				if (end != std::string::npos) {
					line.assign(_buffer, _at, end - _at);
					if (!line.empty() && line.back() == '\r') line.pop_back();
					_at = end + 1;
					return true;
				}
				if (!fill()) return false;
			}
		}

		bool read_bytes(size_t count, std::string& out)
		{
			while (_buffer.size() - _at < count) {
				if (!fill()) return false;
			}
			out.assign(_buffer, _at, count);
			_at += count;
			return true;
		}
	};

	int lsp_main(int argc, char** argv)
	{
		for (int i = 1; i < argc; i++) {
			if (!std::strcmp(argv[i], "--version") || !std::strcmp(argv[i], "-v")) {
				std::printf("blitz-lsp %s\n", BLITZLLVM_VERSION);
				return 0;
			}
			if (!std::strcmp(argv[i], "--help") || !std::strcmp(argv[i], "-h")) {
				std::printf("blitz-lsp: language server for BlitzBasic, Blitz3D, BlitzPlus and BlitzLLVM programs.\n"
							"Speaks the Language Server Protocol over standard input and output (--stdio, the default).\n"
							"Environment: BLITZLLVM_USERLIBS (userlibs directory), BLITZLLVM_COMMANDS (commands.txt)\n");
				return 0;
			}
		}

		// The protocol owns standard output; whatever else writes to it would corrupt the stream, so the library code gets standard error.
#if defined(_WIN32)
		_setmode(0, _O_BINARY);
		FILE* out = _fdopen(_dup(1), "wb");
		_dup2(2, 1);
#else
		FILE* out = fdopen(dup(1), "wb");
		dup2(2, 1);
#endif
		if (!out) return 2;

		blitz::lsp::server server(
			[out](blitz::lsp::json const& message) {
				std::string body = message.dump();
				std::fprintf(out, "Content-Length: %zu\r\n\r\n", body.size());
				std::fwrite(body.data(), 1, body.size(), out);
				std::fflush(out);
			},
			find_data("BLITZLLVM_COMMANDS", "commands.txt", false), find_data("BLITZLLVM_USERLIBS", "userlibs", true));

		input in;
		for (;;) {
			// Nothing waiting: the editor is idle, so this is when the changed files are checked.
			if (!in.pending() && server.has_pending_work()) server.idle();
			size_t      length = 0;
			std::string line;
			bool        have_length = false;
			for (;;) {
				if (!in.read_line(line)) return server.exit_code();
				if (line.empty()) break;
				if (line.compare(0, 15, "Content-Length:") == 0) {
					length      = size_t(std::strtoull(line.c_str() + 15, nullptr, 10));
					have_length = true;
				}
			}
			if (!have_length) continue;
			std::string body;
			if (!in.read_bytes(length, body)) return server.exit_code();
			try {
				if (!server.handle(blitz::lsp::json::parse(body))) return server.exit_code();
			} catch (std::exception const& ex) {
				std::fprintf(stderr, "blitz-lsp: %s\n", ex.what());
			}
		}
	}
} // namespace

int main(int argc, char** argv)
{
	return blitz::run_with_large_stack(lsp_main, argc, argv);
}
